fn prime_num(n: u64) -> bool {
    // By convention we treat numbers less than 2 as non-prime,
    // although the problem states n >= 2.
    if n < 2 {
        return false;
    }
    // 2 is prime.
    if n == 2 {
        return true;
    }
    // Exclude even numbers greater than 2.
    if n % 2 == 0 {
        return false;
    }
    // Test odd divisors up to √n.
    let mut i = 3;
    // Cast to u128 to avoid overflow when computing i*i.
    while (i as u128) * (i as u128) <= n as u128 {
        if n % i == 0 {
            return false;
        }
        i += 2;
    }
    true
}